import java.util.*;import java.nio.file.*;import io.github.r3neer.scalebrews.collision.pose.NumericPoseProgram;import io.github.r3neer.scalebrews.collision.pose.NumericPoseProgram.*;import io.github.r3neer.scalebrews.collision.geometry.ModelGeometry;import io.github.r3neer.scalebrews.collision.api.spi.PoseEngine;import org.joml.Matrix4f;
public final class S56IndependentNumericProof {
static void check(boolean value,String why){if(!value)throw new AssertionError("S56 NUMERIC "+why);}
static Node constant(float f){return new Node(Op.CONSTANT,-1,-1,f,null,null,-1);}
static Node op(Op op,int a,int b){return new Node(op,a,b,0,null,null,-1);}
static ModelGeometry geometry(){var p=new ModelGeometry.SourcePose(3,-2,1,.3f,-.2f,.1f,-1.2f,.7f,1.4f);return new ModelGeometry(2,"independent-numeric","1",List.of(new ModelGeometry.Part("root",null,ModelGeometry.values(p.matrix()),p)),List.of(),ModelGeometry.values(new Matrix4f()));}
static NumericPoseProgram program(List<Node> n,int node,int field){return new NumericPoseProgram(1,"independent","1",geometry(),n,List.of(new Write("root",field,node)));}
static PoseEngine.Inputs input(boolean ordinary,Map<String,Float> c){return new PoseEngine.Inputs(0,0,0,0,0,ordinary,c);}
static void bad(Runnable test){try{test.run();throw new AssertionError("S56 NUMERIC malformed admitted");}catch(IllegalArgumentException expected){}}
static void x(List<Node> nodes,int target,float expected){var p=program(nodes,target,0);var f=p.bind(p.geometry()).orElseThrow();var result=f.evaluate(input(true,Map.of())).orElseThrow().get("root");check(Float.floatToRawIntBits(result.m30())==Float.floatToRawIntBits(expected/16f),"float operation result "+result.m30()+" expected="+expected/16f);}
static void replay(String path)throws Exception {var json=com.google.gson.JsonParser.parseString(Files.readString(Path.of(path))).getAsJsonArray();int count=0;for(var row:json){var o=row.getAsJsonObject();var program=new com.google.gson.Gson().fromJson(o.get("program"),NumericPoseProgram.class);var bound=program.bind(program.geometry()).orElseThrow();for(var sample:o.getAsJsonArray("samples")){var so=sample.getAsJsonObject();var inputs=new TreeMap<String,Float>();so.getAsJsonObject("channels").entrySet().forEach(e->inputs.put(e.getKey(),e.getValue().getAsFloat()));var matrices=program.geometry().transforms(bound.evaluate(input(true,inputs)).orElseThrow());for(var e:so.getAsJsonObject("matrices").entrySet()){float[] data=new float[16];for(int i=0;i<16;i++)data[i]=e.getValue().getAsJsonArray().get(i).getAsFloat();check(new Matrix4f().set(data).equals(matrices.get(e.getKey()),3e-6f),"original replay differs "+e.getKey());count++;}}}System.out.println("S56_NATIVE_COMMON_REPLAY_PASS matrices="+count+" clientVeto=true");}
public static void main(String[] args)throws Exception {if(args.length>0&&Files.isRegularFile(Path.of(args[0])))replay(args[0]);
x(List.of(constant(16777216f),constant(1f),op(Op.ADD,0,1),op(Op.SUBTRACT,2,0)),3,0f);x(List.of(constant(-3.5f),constant(.7f),op(Op.MULTIPLY,0,1),op(Op.DIVIDE,2,1)),3,(-3.5f*.7f)/.7f);x(List.of(constant(0f),op(Op.NEGATE,0,-1)),1,-0f);
for(Op trig:List.of(Op.SIN,Op.COS)){float f=-23.7713f;x(List.of(constant(f),op(trig,0,-1)),1,trig==Op.SIN?net.minecraft.util.Mth.sin((double)f):net.minecraft.util.Mth.cos((double)f));}
for(var nodes:List.of(List.of(constant(0f),op(Op.DIVIDE,0,0),op(Op.SIN,1,-1)),List.of(constant(Float.MAX_VALUE),constant(2),op(Op.MULTIPLY,0,1),op(Op.COS,2,-1)))){var p=program(nodes,nodes.size()-1,0);check(p.bind(p.geometry()).orElseThrow().evaluate(input(true,Map.of())).isEmpty(),"invalid intermediate revived through trig");}
var zero=program(List.of(constant(0)),0,6);check(zero.bind(zero.geometry()).orElseThrow().evaluate(input(true,Map.of())).isEmpty(),"degenerate matrix admitted");var negative=program(List.of(constant(-2)),0,6);check(negative.bind(negative.geometry()).orElseThrow().evaluate(input(true,Map.of())).isPresent(),"signed scale rejected");
var channel=program(List.of(new Node(Op.INPUT,-1,-1,0,"phase",null,-1)),0,0);var bound=channel.bind(channel.geometry()).orElseThrow();check(bound.evaluate(input(true,Map.of())).isEmpty()&&bound.evaluate(input(false,Map.of("phase",2f))).isEmpty()&&bound.evaluate(null).isEmpty(),"missing/incompatible accepted");check(bound.evaluate(input(true,Map.of("phase",2f))).orElseThrow().get("root").m30()==.125f,"input channel changed");var altered=new ModelGeometry(2,"foreign","1",channel.geometry().parts(),List.of(),channel.geometry().modelTransform());check(channel.bind(altered).isEmpty(),"foreign exact binding admitted");var first=bound.evaluate(input(true,Map.of("phase",2f))).orElseThrow();first.get("root").m30(99);check(bound.evaluate(input(true,Map.of("phase",2f))).orElseThrow().get("root").m30()==.125f,"result aliases private state");try{first.clear();throw new AssertionError("mutable map");}catch(UnsupportedOperationException expected){}
var initial=program(List.of(new Node(Op.INITIAL,-1,-1,0,null,"root",2)),0,0);check(initial.bind(initial.geometry()).orElseThrow().evaluate(input(true,Map.of())).orElseThrow().get("root").m30()==1f/16f,"initial field identity");
bad(()->program(List.of(op(Op.ADD,0,0)),0,0));bad(()->program(List.of(new Node(Op.INITIAL,-1,-1,0,null,"foreign",0)),0,0));bad(()->new NumericPoseProgram(1,"i","1",geometry(),List.of(constant(0)),List.of(new Write("root",0,0),new Write("root",0,0))));bad(()->constant(Float.NaN));bad(()->constant(Float.POSITIVE_INFINITY));
var cap=new ArrayList<Node>();for(int i=0;i<512;i++)cap.add(constant(1));check(program(cap,511,0).bind(geometry()).isPresent(),"exact node cap");cap.add(constant(1));bad(()->program(cap,512,0));var schema=new ArrayList<Node>();for(int i=0;i<64;i++)schema.add(new Node(Op.INPUT,-1,-1,0,"k"+i,null,-1));check(program(schema,63,0).bind(geometry()).isPresent(),"exact schema cap");schema.add(new Node(Op.INPUT,-1,-1,0,"overflow",null,-1));bad(()->program(schema,64,0));
java.util.stream.IntStream.range(0,8).parallel().forEach(t->{for(int i=0;i<1000;i++)check(bound.evaluate(input(true,Map.of("phase",(float)t))).orElseThrow().get("root").m30()==t/16f,"concurrent scratch shared");});
var values=input(true,Map.of("phase",2f));for(int i=0;i<100000;i++)check(bound.evaluate(values).orElseThrow().get("root").m30()==.125f,"unstable warm result");var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();bean.setThreadAllocatedMemoryEnabled(true);long tid=Thread.currentThread().threadId(),before=bean.getThreadAllocatedBytes(tid);float sum=0;for(int i=0;i<100000;i++)sum+=bound.evaluate(values).orElseThrow().get("root").m30();long bytes=bean.getThreadAllocatedBytes(tid)-before;check(sum==12500f,"measured result");System.out.println("S56_INDEPENDENT_NUMERIC_PASS IEEE/trig/initial/binding/null/missing/degenerate/512/64/concurrent8000 allocation100k="+bytes);
}}
